-- AAGLA Golf: seed the Iowa chapter from the original Google Sheet.
--
-- A one-time data migration, kept as a migration so a fresh database can be
-- rebuilt from `supabase/migrations/` alone. Every insert resolves its foreign
-- keys by joining on legacy_id, so no generated UUID is ever hardcoded.
--
-- Source: "AAGLA Data Set - Iowa Chapter", tabs App Players / App Events /
-- App Scores / App Handicaps / App Config, exported 2026-08-01.
--
-- Two deliberate deviations from the source data, both documented in
-- docs/MIGRATION.md:
--   * 3 exactly-duplicated App Handicaps rows are collapsed to one. They were
--     an artifact of getHandicapOverview()'s unguarded batch append; the FS
--     value and note are identical in every copy, so nothing is lost.
--   * 6 App Handicaps rows carrying a blank FS are dropped. Every one belongs
--     to a player with zero rounds that season -- placeholder columns on the
--     old Free Strokes tab for people who were not in the league that year. A
--     locked handicap with no value is not a locked handicap, and the absence
--     of a row already means "not locked yet", so this loses no information.
--   * Historical place/points are imported verbatim and never recomputed.

insert into public.leagues (slug, name, chapter, public_board)
values ('aagla-iowa', 'AAGLA Iowa Chapter', 'Iowa', true);

-- One season per year the league has played. Rules are seeded from App Config
-- (handicapBestOf = 3, handicapWindowEvents = 7) and the points table default.
insert into public.seasons (league_id, year)
select l.id, y
from public.leagues l, generate_series(2013, 2026) as y
where l.slug = 'aagla-iowa';

insert into public.players (league_id, legacy_id, name, status, first_year)
select l.id, v.legacy_id, v.name, v.status::public.player_status, v.first_year
from (values (1,'Josh Ingalls','inactive',2013),(2,'Hayden Zeidler','active',2013),(3,'London Usher','active',2013),(4,'Ryan Lameroux','inactive',2015),(5,'Brent Cunningham','active',2017),(6,'John Gookin','active',2017),(7,'BJ Neal','inactive',2017),(8,'Mark Judge','active',2017),(9,'Rod Hager','active',2018),(10,'Will Ice','inactive',2018),(11,'Bill Ice','inactive',2018),(12,'David Back','active',2021),(13,'Mark Diacono','inactive',2021),(14,'Jeremy Thornburg','inactive',2021),(15,'Matt Kuiper','inactive',2022),(16,'Angelo Gutierrez','inactive',2022),(17,'Loren Robbins','inactive',2022),(18,'Logan Hammel','inactive',2022),(19,'Trevor Fernau','inactive',2022),(20,'Taylor Musselman','active',2023),(21,'Josh Ramos','inactive',2023),(22,'Anthony Dworak','inactive',2023),(23,'Jansel Herrera','active',2024),(24,'Tim Paccione','inactive',2024),(25,'Josh Rudman','inactive',2024),(26,'Michael Olson','active',2026)) as v(legacy_id, name, status, first_year)
join public.leagues l on l.slug = 'aagla-iowa';

insert into public.player_contacts (player_id, league_id, email)
select p.id, l.id, v.email
from (values (1,'jingalls20@gmail.com'),(2,'hayden.zeidler@gmail.com'),(3,'London.usher@gmail.com'),(5,'TIfsport321@gmail.com'),(8,'markjudge2000@gmail.com'),(20,'tmusselman13@gmail.com'),(26,'Michael.olson93@gmail.com')) as v(legacy_id, email)
join public.leagues l on l.slug = 'aagla-iowa'
join public.players p on p.league_id = l.id and p.legacy_id = v.legacy_id;

